<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { RouterLink, useRoute, useRouter } from 'vue-router'
import AdminPagination from '../components/AdminPagination.vue'
import AdminState from '../components/AdminState.vue'
import AdminTable from '../components/AdminTable.vue'
import { adminApi } from '../api/adminApi'
import { periodSchema } from '../schemas/adminSchemas'
import type { AdminExam, Career, EnrollmentPeriod, Subject } from '../types/admin'
import { useFeedback } from '@/ui/feedback'
import { academicLabel } from '@/core/presentation/academicLabels'
import { calculatePeriodStatus, formatArgentinaDate, periodDateRange, periodScope, periodStatusLabel, periodTitle, toArgentinaDateTimeLocal, toArgentinaIso } from '../periodsPresentation'

const route = useRoute(); const router = useRouter(); const feedback = useFeedback()
const periods = ref<EnrollmentPeriod[]>([]); const careers = ref<Career[]>([]); const subjectsByYear = ref<Array<{ anio: number | null; materias: Subject[] }>>([]); const selected = ref<EnrollmentPeriod | null>(null)
const loading = ref(false); const error = ref(''); const saving = ref(false); const pagination = ref({ page: 1, limit: 20, total: 0, totalPages: 0 }); const cycle = ref(String(route.query.cicloLectivo ?? ''))
const exams = ref<AdminExam[]>([]); const examPageIds = ref<number[]>([]); const examPage = ref(1); const examPagination = ref({ page: 1, limit: 100, total: 0, totalPages: 0 }); const examLoading = ref(false); const examError = ref('')
let disposed = false; let listRequest = 0; let detailRequest = 0; let formRequest = 0; let subjectsRequest = 0; let examsRequest = 0
const form = reactive({ tipo: 'MATERIA' as 'MATERIA' | 'EXAMEN', cicloLectivo: new Date().getFullYear(), fechaInicio: '', fechaFin: '', materiasIds: [] as number[], mesasIds: [] as number[], descripcion: '' }); const careerId = ref<number | null>(null); const fieldError = ref('')
const mode = computed(() => String(route.name)); const isList = computed(() => mode.value === 'admin-periods'); const isDetail = computed(() => mode.value === 'admin-period-detail'); const id = computed(() => Number(route.params.id)); const isExam = computed(() => form.tipo === 'EXAMEN')
const visibleExams = computed(() => exams.value.filter((exam) => examPageIds.value.includes(exam.id) || form.mesasIds.includes(exam.id)))

function currentStatus(period: EnrollmentPeriod) { return period.estado ?? calculatePeriodStatus(period) }
function subjectId(item: Subject | { materia: Subject; materiaId: number }) { return 'materiaId' in item ? item.materiaId : item.id }
function toggleId(ids: number[], value: number) { return ids.includes(value) ? ids.filter((id) => id !== value) : [...ids, value] }
function toggleSubject(value: number) { form.materiasIds = toggleId(form.materiasIds, value) }
function toggleExam(value: number) { form.mesasIds = toggleId(form.mesasIds, value) }
async function loadList() { const current = ++listRequest; loading.value = true; error.value = ''; try { const result = await adminApi.listPeriods({ cicloLectivo: cycle.value ? Number(cycle.value) : undefined, page: Number(route.query.page ?? 1) }); if (disposed || current !== listRequest) return; periods.value = result.data; pagination.value = result.pagination } catch { if (!disposed && current === listRequest) error.value = 'No pudimos cargar los períodos.' } finally { if (!disposed && current === listRequest) loading.value = false } }
async function loadCareers(token: number) { try { const result = await adminApi.listCareers({ limit: 100 }); if (!disposed && token === formRequest) careers.value = result.data } catch { if (!disposed && token === formRequest) careers.value = [] } }
async function loadSubjects() { const career = careerId.value; const token = ++subjectsRequest; if (!career) { subjectsByYear.value = []; return }; try { const result = await adminApi.getSubjectsByYear(career); if (!disposed && token === subjectsRequest && careerId.value === career && mode.value !== 'admin-period-detail') subjectsByYear.value = result } catch { if (!disposed && token === subjectsRequest && careerId.value === career) subjectsByYear.value = [] } }
function mergeExams(next: AdminExam[]) { const byId = new Map(exams.value.map((exam) => [exam.id, exam])); next.forEach((exam) => byId.set(exam.id, exam)); exams.value = [...byId.values()] }
async function loadExamsPage(page = examPage.value) { const token = ++examsRequest; const targetRoute = route.fullPath; examPage.value = page; examLoading.value = true; examError.value = ''; try { const result = await adminApi.listExams({ page, limit: 100 }); if (disposed || token !== examsRequest || route.fullPath !== targetRoute || form.tipo !== 'EXAMEN') return; examPageIds.value = result.data.map((exam) => exam.id); mergeExams(result.data); examPagination.value = result.pagination } catch { if (!disposed && token === examsRequest && route.fullPath === targetRoute && form.tipo === 'EXAMEN') examError.value = 'No pudimos cargar las mesas de examen.' } finally { if (!disposed && token === examsRequest) examLoading.value = false } }
async function loadDetail() { const token = ++detailRequest; const targetRoute = route.fullPath; loading.value = true; error.value = ''; try { const result = await adminApi.getPeriod(id.value); if (disposed || token !== detailRequest || route.fullPath !== targetRoute) return; selected.value = result } catch { if (!disposed && token === detailRequest && route.fullPath === targetRoute) error.value = 'No pudimos cargar el período.' } finally { if (!disposed && token === detailRequest) loading.value = false } }
function resetForm() { Object.assign(form, { tipo: 'MATERIA', cicloLectivo: new Date().getFullYear(), fechaInicio: '', fechaFin: '', materiasIds: [], mesasIds: [], descripcion: '' }); careerId.value = null; fieldError.value = '' }
async function loadForm() { const token = ++formRequest; const targetRoute = route.fullPath; resetForm(); await loadCareers(token); if (disposed || token !== formRequest || route.fullPath !== targetRoute) return; if (mode.value !== 'admin-period-edit') return; try { const period = await adminApi.getPeriod(id.value); if (disposed || token !== formRequest || route.fullPath !== targetRoute) return; selected.value = period; Object.assign(form, { tipo: period.tipo, cicloLectivo: period.cicloLectivo, fechaInicio: toArgentinaDateTimeLocal(period.fechaInicio), fechaFin: toArgentinaDateTimeLocal(period.fechaFin), materiasIds: (period.materias ?? []).map(subjectId), mesasIds: (period.mesas ?? []).map((item) => item.mesaId), descripcion: period.descripcion ?? '' }); if (form.tipo === 'EXAMEN') { const selectedExams = (period.mesas ?? []).flatMap((item) => item.mesa ? [item.mesa] : []); mergeExams(selectedExams); await loadExamsPage(1) } } catch { if (!disposed && token === formRequest && route.fullPath === targetRoute) fieldError.value = 'No pudimos cargar el período para editar.' } }
function handleTypeChange(event: Event) { const type = (event.target as HTMLSelectElement).value as 'MATERIA' | 'EXAMEN'; if (form.tipo === type) return; form.tipo = type; if (type === 'EXAMEN') { form.materiasIds = []; form.mesasIds = []; exams.value = []; examPageIds.value = []; examPage.value = 1; void loadExamsPage(1) } else { form.mesasIds = []; ++examsRequest; exams.value = []; examPageIds.value = []; examError.value = ''; examLoading.value = false } }
function apply() { void router.replace({ query: { cicloLectivo: cycle.value || undefined, page: undefined } }).then(loadList) }
function resetFilter() { cycle.value = ''; apply() }
async function save() { fieldError.value = ''; const result = periodSchema.safeParse(form); if (!result.success) { fieldError.value = result.error.issues[0]?.message ?? 'Revisá los datos.'; return }; saving.value = true; try { const { tipo, cicloLectivo, descripcion, materiasIds, mesasIds, fechaInicio, fechaFin } = result.data; const payload = { tipo, cicloLectivo, descripcion, fechaInicio: toArgentinaIso(fechaInicio), fechaFin: toArgentinaIso(fechaFin), ...(tipo === 'EXAMEN' ? { mesasIds } : { materiasIds }) }; if (mode.value === 'admin-period-create') await adminApi.createPeriod(payload); else await adminApi.updatePeriod(id.value, payload); feedback.success(mode.value === 'admin-period-create' ? 'Período creado.' : 'Período actualizado.'); await router.replace({ name: 'admin-periods', query: route.query }) } catch { feedback.error('No se pudo guardar el período.') } finally { saving.value = false } }
async function deactivate() { if (!selected.value || !window.confirm('¿Desactivar este período?')) return; try { await adminApi.deactivatePeriod(selected.value.id); feedback.success('Período desactivado.'); await router.replace({ name: 'admin-periods', query: route.query }) } catch { feedback.error('No se pudo desactivar el período.') } }
function pageUrl(page: number) { return { query: { ...route.query, page: String(page) } } }
function statusClass(status: string) { return { DESACTIVADO: 'bg-gray-100 text-gray-700', PROGRAMADO: 'bg-amber-100 text-amber-900', ABIERTO: 'bg-green-100 text-green-900', FINALIZADO: 'bg-red-100 text-red-900' }[status] ?? 'bg-gray-100 text-gray-700' }
watch(careerId, () => void loadSubjects()); watch(() => route.fullPath, () => { ++detailRequest; ++formRequest; ++subjectsRequest; ++examsRequest; if (isList.value) void loadList(); else if (isDetail.value) void loadDetail(); else void loadForm() }); onMounted(() => { if (isList.value) void loadList(); else if (isDetail.value) void loadDetail(); else void loadForm() }); onUnmounted(() => { disposed = true; ++listRequest; ++detailRequest; ++formRequest; ++subjectsRequest; ++examsRequest })
</script>

<template>
  <main aria-labelledby="admin-periods-title" class="mx-auto max-w-6xl">
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-semibold uppercase tracking-[0.14em] text-[var(--color-brand)]">Administración</p><h1 id="admin-periods-title" class="mt-2 text-3xl font-semibold">Períodos de inscripción</h1></div><RouterLink v-if="isList" :to="{ name: 'admin-period-create' }" class="min-h-11 rounded-lg bg-[var(--color-brand)] px-4 py-2.5 font-semibold text-white">Nuevo período</RouterLink></div>
    <template v-if="isList"><form class="mt-6 flex max-w-xl flex-wrap items-end gap-3 rounded-xl border border-[var(--color-border)] bg-white p-4" @submit.prevent="apply"><label class="min-w-48 flex-1 text-sm font-semibold">Ciclo lectivo<input v-model="cycle" inputmode="numeric" aria-label="Ciclo lectivo" class="admin-input" /></label><button class="min-h-11 rounded-lg bg-[var(--color-brand)] px-4 font-semibold text-white">Aplicar</button><button v-if="cycle" type="button" class="min-h-11 rounded-lg border border-[var(--color-border)] px-4 font-semibold" @click="resetFilter">Limpiar</button></form><div class="mt-5"><AdminState :loading="loading" :error="error" :empty="!loading && !error && !periods.length" empty-text="No hay períodos para mostrar." @retry="loadList"><AdminTable :columns="[{ key: 'period', label: 'Período' }, { key: 'dates', label: 'Apertura y cierre' }, { key: 'scope', label: 'Alcance' }, { key: 'status', label: 'Estado' }]"><template #rows><tr v-for="period in periods" :key="period.id" class="border-t border-[var(--color-border)]"><td class="px-4 py-4"><RouterLink :to="{ name: 'admin-period-detail', params: { id: period.id }, query: route.query }" class="font-semibold text-[var(--color-brand)]">{{ periodTitle(period) }}</RouterLink><p v-if="period.descripcion" class="mt-1 text-sm text-[var(--color-graphite)]">{{ period.descripcion }}</p></td><td class="px-4 py-4 text-sm">{{ periodDateRange(period) }}</td><td class="px-4 py-4 text-sm">{{ periodScope(period) }}</td><td class="px-4 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="statusClass(currentStatus(period))">{{ periodStatusLabel(currentStatus(period)) }}</span></td><td class="px-4 py-4 text-right"><div class="flex justify-end gap-3"><RouterLink :to="{ name: 'admin-period-detail', params: { id: period.id }, query: route.query }" class="font-semibold text-[var(--color-brand)]">Ver detalle</RouterLink><RouterLink :to="{ name: 'admin-period-edit', params: { id: period.id }, query: route.query }" class="font-semibold text-[var(--color-brand)]">Editar</RouterLink></div></td></tr></template><template #cards><article v-for="period in periods" :key="period.id" class="rounded-lg border border-[var(--color-border)] p-4"><h2 class="text-base font-semibold"><RouterLink :to="{ name: 'admin-period-detail', params: { id: period.id }, query: route.query }" class="text-[var(--color-brand)]">{{ periodTitle(period) }}</RouterLink></h2><p v-if="period.descripcion" class="mt-1 text-sm text-[var(--color-graphite)]">{{ period.descripcion }}</p><dl class="mt-3 grid gap-2 text-sm"><div><dt class="font-semibold">Apertura y cierre</dt><dd>{{ periodDateRange(period) }}</dd></div><div><dt class="font-semibold">Alcance</dt><dd>{{ periodScope(period) }}</dd></div><div><dt class="font-semibold">Estado</dt><dd><span class="font-semibold">{{ periodStatusLabel(currentStatus(period)) }}</span></dd></div></dl><div class="mt-4 flex gap-4"><RouterLink :to="{ name: 'admin-period-detail', params: { id: period.id }, query: route.query }" class="font-semibold text-[var(--color-brand)]">Ver detalle</RouterLink><RouterLink :to="{ name: 'admin-period-edit', params: { id: period.id }, query: route.query }" class="font-semibold text-[var(--color-brand)]">Editar</RouterLink></div></article></template></AdminTable><AdminPagination :pagination="pagination" @change="(page) => router.replace(pageUrl(page)).then(loadList)" /></AdminState></div></template>
    <template v-else-if="isDetail"><AdminState :loading="loading" :error="error" @retry="loadDetail"><section v-if="selected" class="mt-7 rounded-xl border border-[var(--color-border)] bg-white p-6"><div class="flex flex-wrap items-start justify-between gap-4"><div><h2 class="text-2xl font-semibold">{{ periodTitle(selected) }}</h2><p class="mt-1 text-[var(--color-graphite)]">{{ periodDateRange(selected) }} · {{ periodStatusLabel(currentStatus(selected)) }}</p><p v-if="selected.descripcion" class="mt-2 text-[var(--color-graphite)]">{{ selected.descripcion }}</p></div><div class="flex gap-2"><RouterLink :to="{ name: 'admin-period-edit', params: { id: selected.id }, query: route.query }" class="min-h-10 rounded-lg bg-[var(--color-brand)] px-4 py-2 font-semibold text-white">Editar</RouterLink><button type="button" class="min-h-10 rounded-lg border border-[var(--color-border)] px-4 py-2" :disabled="!selected.activo" @click="deactivate">Desactivar</button></div></div><h3 class="mt-7 text-xl font-semibold">{{ selected.tipo === 'EXAMEN' ? 'Mesas habilitadas' : 'Materias habilitadas' }}</h3><ul v-if="selected.tipo === 'MATERIA'" class="mt-3 grid gap-2 sm:grid-cols-2"><li v-for="item in selected.materias ?? []" :key="subjectId(item)" class="rounded-lg bg-[#f6f7f4] p-3">{{ 'materia' in item ? item.materia.nombre : item.nombre }}</li></ul><ul v-else class="mt-3 grid gap-2 sm:grid-cols-2"><li v-for="item in selected.mesas ?? []" :key="item.mesaId" class="rounded-lg bg-[#f6f7f4] p-3">{{ item.mesa?.materia?.nombre ?? `Mesa ${item.mesaId}` }}</li></ul><p v-if="selected.tipo === 'MATERIA' && !selected.materias?.length || selected.tipo === 'EXAMEN' && !selected.mesas?.length" class="mt-3 text-sm text-[var(--color-graphite)]">No hay elementos informados en el detalle.</p></section></AdminState></template>
<template v-else><section class="mt-7 max-w-3xl rounded-xl border border-[var(--color-border)] bg-white p-6"><h2 class="text-2xl font-semibold">{{ mode === 'admin-period-create' ? 'Nuevo período de inscripción' : 'Editar período de inscripción' }}</h2><form class="mt-5 grid gap-4 sm:grid-cols-2" @submit.prevent="save"><label class="font-semibold">Tipo de inscripción<select :value="form.tipo" aria-label="Tipo de inscripción" class="admin-input" @change="handleTypeChange"><option value="MATERIA">Materias</option><option value="EXAMEN">Exámenes</option></select></label><label class="font-semibold">Ciclo lectivo<input v-model.number="form.cicloLectivo" type="number" class="admin-input" /></label><label class="font-semibold">Apertura<input v-model="form.fechaInicio" type="datetime-local" class="admin-input" /></label><label class="font-semibold">Cierre<input v-model="form.fechaFin" type="datetime-local" class="admin-input" /></label><p class="sm:col-span-2 text-sm text-[var(--color-graphite)]">Las fechas se interpretan en la zona horaria institucional: America/Argentina/Buenos_Aires.</p><template v-if="!isExam"><label class="font-semibold sm:col-span-2">Carrera<select v-model.number="careerId" class="admin-input"><option :value="null">Seleccionar carrera</option><option v-for="career in careers" :key="career.id" :value="career.id">{{ career.nombre }}</option></select></label><fieldset class="sm:col-span-2"><legend class="font-semibold">Materias habilitadas</legend><p class="mt-1 text-sm text-[var(--color-graphite)]">Seleccioná una carrera y luego las materias por año.</p><div v-for="group in subjectsByYear" :key="String(group.anio)" class="mt-3 rounded-lg border border-[var(--color-border)] p-3"><h3 class="font-semibold">{{ group.anio ?? 'Sin año' }}° año</h3><label v-for="subject in group.materias" :key="subject.id" class="mt-2 flex min-h-11 items-center gap-2 text-sm"><input type="checkbox" :checked="form.materiasIds.includes(subject.id)" @change="toggleSubject(subject.id)" />{{ subject.nombre }}</label></div></fieldset></template><fieldset v-else class="sm:col-span-2"><legend class="font-semibold">Mesas habilitadas</legend><p class="mt-1 text-sm text-[var(--color-graphite)]">Seleccioná las mesas concretas que podrán recibir inscripciones.</p><div v-if="examLoading" class="mt-3 rounded-lg bg-[#f6f7f4] p-4 text-sm" role="status">Cargando mesas de examen…</div><div v-else-if="examError" class="mt-3 rounded-lg border border-red-200 bg-red-50 p-4 text-sm text-red-800" role="alert"><p>{{ examError }}</p><button type="button" class="mt-3 min-h-10 rounded-lg bg-[var(--color-brand)] px-4 font-semibold text-white" @click="loadExamsPage(examPage)">Reintentar mesas</button></div><div v-else-if="!visibleExams.length" class="mt-3 rounded-lg bg-[#f6f7f4] p-4 text-sm text-[var(--color-graphite)]">No hay mesas activas disponibles para seleccionar.</div><template v-else><label v-for="exam in visibleExams" :key="exam.id" class="mt-2 flex min-h-11 items-center gap-2 rounded-lg border border-[var(--color-border)] p-3 text-sm"><input type="checkbox" :checked="form.mesasIds.includes(exam.id)" @change="toggleExam(exam.id)" /><span><strong>{{ exam.materia.nombre }}</strong> · {{ formatArgentinaDate(exam.fecha) }} · {{ academicLabel(exam.tipoExamen) }} · llamado {{ exam.llamado }}</span></label><div v-if="examPagination.totalPages > 1" class="mt-4 flex items-center justify-between gap-3 text-sm"><button type="button" class="min-h-10 rounded-lg border border-[var(--color-border)] px-3 font-semibold" :disabled="examPage <= 1 || examLoading" @click="loadExamsPage(examPage - 1)">Página anterior</button><span>Página {{ examPage }} de {{ examPagination.totalPages }}</span><button type="button" class="min-h-10 rounded-lg border border-[var(--color-border)] px-3 font-semibold" :disabled="examPage >= examPagination.totalPages || examLoading" @click="loadExamsPage(examPage + 1)">Página siguiente</button></div></template></fieldset><label class="font-semibold sm:col-span-2">Descripción<textarea v-model="form.descripcion" class="admin-input min-h-20"></textarea></label><p v-if="fieldError" class="field-error sm:col-span-2" role="alert">{{ fieldError }}</p><div class="flex gap-3 sm:col-span-2"><button type="submit" class="min-h-11 rounded-lg bg-[var(--color-brand)] px-5 font-semibold text-white" :disabled="saving">{{ saving ? 'Guardando…' : 'Guardar período' }}</button><RouterLink :to="{ name: 'admin-periods', query: route.query }" class="min-h-11 rounded-lg border border-[var(--color-border)] px-5 py-2.5">Cancelar</RouterLink></div></form></section></template>
  </main>
</template>

<style scoped>.admin-input{margin-top:.25rem;min-height:2.75rem;width:100%;border:1px solid var(--color-border);border-radius:.5rem;padding:0 .75rem;font-weight:400}.field-error{font-size:.875rem;color:#a31118}</style>
